function workflow(workflowType:WorkflowJob['workflowType']):WorkflowJob{const now=new Date().toISOString();return{id:randomUUID(),tenantId:tenantA.tenantId,locationId:tenantA.locationId,workflowType,correlationId:randomUUID(),causationEventId:randomUUID(),dedupeKey:randomUUID(),runAt:now,status:'pending',attempts:0,maxAttempts:5,payload:{},createdAt:now,updatedAt:now}}
function methodBody(source:string,name:string){const start=source.indexOf(`async ${name}(`);expect(start,`${name} method`).toBeGreaterThanOrEqual(0);const next=source.indexOf('\n  async ',start+1);return source.slice(start,next<0?source.length:next)}
